use vstd::prelude::*;

verus! {

spec fn out_at(a: nat, b: nat, c1: bool, c2: bool) -> nat {
    if c1 && c2 {
        (a + b) / 2
    } else if c1 && !c2 {
        a
    } else {
        // includes the (false,true) case; (false,false) is ruled out by precondition
        b
    }
}

fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
)
    requires
        vals_2.len() == vals_1.len(),
        conds_1.len() == vals_1.len(),
        conds_2.len() == vals_1.len(),
        // runtime asserts in the loop:
        forall|i: int|
            0 <= i < vals_1.len() ==> (conds_1[i] || conds_2[i]),
        forall|i: int|
            0 <= i < vals_1.len() ==> (vals_1[i] < 1000 && vals_2[i] < 1000),
    ensures
        avgs.len() == vals_1.len(),
        forall|i: int|
            0 <= i < vals_1.len() ==> avgs[i] as nat
                == out_at(vals_1[i] as nat, vals_2[i] as nat, conds_1[i], conds_2[i]),
{
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 length must match vals_1");
    assert_eq!(conds_1.len(), n, "conds_1 length must match vals_1");
    assert_eq!(conds_2.len(), n, "conds_2 length must match vals_1");

    avgs.clear();
    avgs.reserve(n);

    for i in 0..n
        invariant
            n == vals_1.len(),
            vals_2.len() == n,
            conds_1.len() == n,
            conds_2.len() == n,
            0 <= i <= n,
            avgs.len() == i,
            forall|j: int|
                0 <= j < i ==> (conds_1[j] || conds_2[j]),
            forall|j: int|
                0 <= j < i ==> (vals_1[j] < 1000 && vals_2[j] < 1000),
            forall|j: int|
                0 <= j < i ==> avgs[j] as nat
                    == out_at(vals_1[j] as nat, vals_2[j] as nat, conds_1[j], conds_2[j]),
        decreases n - i,
    {
        let c1 = conds_1[i];
        let c2 = conds_2[i];
        assert!(c1 || c2, "at least one condition must be true at each index");

        let a = vals_1[i];
        let b = vals_2[i];
        assert!(a < 1000 && b < 1000, "all integer inputs must be < 1000");

        let out = match (c1, c2) {
            (true, true) => (a + b) / 2,
            (true, false) => a,
            (false, true) => b,
            (false, false) => unreachable!(),
        };

        // Establish the value that will be appended matches the spec.
        assert(out as nat == out_at(a as nat, b as nat, c1, c2));

        avgs.push(out);
    }
}

} // verus!

